"use strict";
(async()=>{const D=await window.loadResearchData('entries-data.json.gz'),$=s=>document.querySelector(s),H=[5,10,20,30,60,120];let profile='stop',focus=20,page=0,visible=[],cleanup=null,opener=null;const size=15;
const pct=v=>v==null?'—':(v>0?'+':'')+(v*100).toFixed(2)+'%',rate=v=>v==null?'—':(v*100).toFixed(2)+'%',num=v=>v==null?'—':Number(v).toFixed(2),day=v=>v?String(v).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3'):'—',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),gain=v=>`<span class="${v>0?'gain':v<0?'loss':''}">${pct(v)}</span>`;
function render(){document.querySelectorAll('[data-profile]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.profile===profile)));const s=D.report.profiles[profile];$('#profile-description').textContent=profile==='direct'?'对照：极致缩量收盘确认后，次日开盘买入，不设止损。':`缩量后20日内，等首根阳线且量>前5日及前10日均量；次日开盘买入。${profile==='stop'?'买入价下方15%全仓止损，T+1及跳空按可实现成交处理。':'不设止损，到期退出。'} 共${s.signals}个放量确认。`;
$('#horizon-rows').innerHTML=s.horizons.map(x=>`<tr${x.horizon===focus?' class="current-variant"':''}><td>${x.horizon}日</td><td>${x.n}<small>${x.stocks}只 / ${x.entry_dates}个买入日</small></td><td>${gain(x.mean)}</td><td>${gain(x.median)}</td><td>${rate(x.win)}</td><td>${num(x.payoff)}</td><td>${gain(x.mean_excess)}</td><td>${x.immature}</td></tr>`).join('');
$('#common-rows').innerHTML=s.common120.map(x=>`<tr><td>${x.horizon}日</td><td>${x.n}</td><td>${gain(x.mean)}</td><td>${rate(x.win)}</td><td>${num(x.payoff)}</td></tr>`).join('');
const k=s.horizons.find(x=>x.horizon===focus),ci=k.block_interval;$('#diagnostic-cards').innerHTML=[['按买入日等权的平均收益',pct(k.date_equal_mean),'每个买入日同等权重'],['平均净收益的区块区间',ci?`${pct(ci.ci95[0])} 至 ${pct(ci.ci95[1])}`:'样本时期不足',ci?ci.blocks+'个半年区块，约95%区间':'不能可靠估计'],['持有期间最大浮亏中位数',pct(k.median_mae),'日内最低价估计，非组合回撤']].map(([a,b,c])=>`<article><p>${a}</p><strong>${b}</strong><p>${c}</p></article>`).join('');
$('#annual-rows').innerHTML=s.annual.filter(x=>x.horizon===focus).map(x=>`<tr><td>${x.year}${x.year===2026?'（部分）':''}</td><td>${x.n}</td><td>${gain(x.mean)}</td><td>${gain(x.median)}</td><td>${rate(x.win)}</td><td>${num(x.payoff)}</td><td>${gain(x.mean_excess)}</td></tr>`).join('');
$('#sensitivity-rows').innerHTML=Object.entries(D.report.profiles).map(([key,v])=>{const x=v.horizons.find(x=>x.horizon===focus);return`<tr${key===profile?' class="current-variant"':''}><td>${v.label}</td><td>${x.n}</td><td>${gain(x.mean)}</td><td>${rate(x.win)}</td><td>${num(x.payoff)}</td><td>${gain(x.mean_excess)}</td></tr>`}).join('');
const matched=D.report.matched.find(x=>x.horizon===focus);$('#matched-rows').innerHTML=['confirm','stop'].map(key=>{const x=matched[key];return`<tr><td>${key==='stop'?'加15%止损':'不止损'}</td><td>${x.n}</td><td>${gain(x.mean)}</td><td>${rate(x.win)}</td><td>${num(x.payoff)}</td><td>${x.stopped}</td></tr>`}).join('');
$('#volume-rows').innerHTML=s.groups.filter(x=>x.horizon===focus&&x.field==='rally_volume_ratio').map(x=>`<tr><td>${x.bucket}倍</td><td>${x.n}</td><td>${gain(x.mean)}</td><td>${rate(x.win)}</td><td>${num(x.payoff)}</td><td>${gain(x.mean_excess)}</td></tr>`).join('');
const t=s.entry_status;$('#execution-note').textContent=`该口径：${t.filled||0}个可开盘买入信号，${t.upper_open||0}个涨停开盘跳过，${t.st_excluded||0}个ST排除，${t.unknown_st||0}个历史状态缺失排除，${t.no_next_bar||0}个无次日行情。当前${focus}日样本中${k.delayed_exits}笔延后退出，${k.unresolved}笔到期但无法完成退出；重叠剔除${k.overlap_removed}笔；其中${k.stopped}笔触发止损。`;filter()}
function filter(){const q=$('#trade-search').value.trim().toLowerCase(),view=$('#sample-view').value,sort=$('#trade-sort').value;visible=D.rows[profile].filter(x=>(!q||(x.name+x.code).toLowerCase().includes(q))&&(view==='upper'?x.entry_status==='upper_open':x.entry_status==='filled'&&(view==='all'||x['included_'+focus])));visible.sort((a,b)=>sort==='date'?b.signal_date-a.signal_date||a.code.localeCompare(b.code):(sort==='best'?-1:1)*((a['net_'+focus]??(sort==='best'?-Infinity:Infinity))-(b['net_'+focus]??(sort==='best'?-Infinity:Infinity))));page=0;$('#download-trades').href=`entries-${profile}-${focus}.csv`;table()}
function table(){const rows=visible.slice(page*size,(page+1)*size);$('#trade-rows').innerHTML=rows.length?rows.map(x=>`<tr><td><button class="research-stock" data-event="${x.event_id}"><strong>${esc(x.name)}</strong><small>${esc(x.code)} · ${day(x.signal_date)}</small></button></td><td>${num(x.buy_price)}</td><td>${rate(x.dry_ratio)}</td>${H.map(h=>`<td>${gain(x['net_'+h])}</td>`).join('')}</tr>`).join(''):'<tr><td colspan="9">没有符合条件的信号</td></tr>';$('#trade-count').textContent=`共 ${visible.length} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(visible.length/size))} 页`;$('#prev-page').disabled=page===0;$('#next-page').disabled=(page+1)*size>=visible.length}
const dialog=$('#research-detail');function detail(x,button){opener=button;dialog.querySelector('.candle-panel h3').textContent=x.name+' · 放量确认与止损';$('#detail-name').textContent=x.name;$('#detail-subtitle').textContent=`${x.code} · 缩量 ${day(x.dry_date)} · ${profile==='direct'?'信号':'放量确认'} ${day(x.signal_date)} · 次日开盘 ${day(x.entry_date)}${x.entry_status==='upper_open'?' · 涨停开盘，仅理论估值':''}`;$('#detail-metrics').innerHTML=[['次日开盘价',num(x.buy_price),'未复权价'],['尾段3日量 / 上涨段量',rate(x.dry_ratio),'尾段 / 前20日 '+rate(x.dry_vs20)],['底部至放量峰涨幅',pct(x.rally),day(x.floor_date)+' → '+day(x.peak_date)],[profile==='stop'?'初始15%止损价':'峰值后回调',profile==='stop'?num(x.stop_price):pct(-x.pullback),profile==='stop'?'T+1 / 跳空可能超出15%':'回吐上涨幅度 '+rate(x.retrace)]].map(([a,b,c])=>`<div><span>${a}</span><b>${b}</b><small>${c}</small></div>`).join('');$('#detail-shape').textContent=`底部收盘 ${num(x.floor_price)}，放量峰收盘 ${num(x.peak_price)}（均为信号日基准）。上涨段均量为底部基准的${num(x.rally_volume_ratio)}倍；整个回调均量为上涨段的${rate(x.wash_volume_ratio)}，尾段5日为${rate(x.tail_volume_ratio)}。${profile==='direct'?'':'确认等待'+x.confirm_wait+'日，量/前5日均量'+num(x.volume5)+'倍、量/前10日均量'+num(x.volume10)+'倍。'}信号日涨跌幅${pct(x.signal_return)}。`;
$('#detail-returns').innerHTML=H.map(h=>`<tr><td>${h}日</td><td>${day(x['exit_date_'+h])}</td><td>${gain(x['net_'+h])}</td><td>${gain(x['benchmark_'+h])}</td><td>${x['status_'+h]==='immature'?'尚未到期':x['status_'+h]==='unresolved'?'到期未能退出':x.entry_status==='upper_open'?'开盘涨停，未计成交':x['included_'+h]?(String(x['reason_'+h]).startsWith('stop_')?'止损退出，余期现金':'到期退出'):'同股持仓重叠，未计入'}</td></tr>`).join('');if(cleanup)cleanup();dialog.showModal();const root=dialog.querySelector('.candle-panel');root.querySelector('canvas').hidden=false;const plot={...x,sell_events:profile==='stop'&&x['exit_date_'+focus]?[{date:x['exit_date_'+focus],signal_price:x['sale_signal_price_'+focus],reason:String(x['reason_'+focus]).startsWith('stop_')?'full_hard15':'expiry'}]:[]};cleanup=window.mountSignalCandles(root,plot,null)}
document.querySelectorAll('[data-profile]').forEach(b=>b.addEventListener('click',()=>{profile=b.dataset.profile;render()}));$('#focus-horizon').addEventListener('change',()=>{focus=Number($('#focus-horizon').value);render()});for(const id of ['sample-view','trade-sort'])$('#'+id).addEventListener('change',filter);$('#trade-search').addEventListener('input',filter);$('#prev-page').addEventListener('click',()=>{page--;table()});$('#next-page').addEventListener('click',()=>{page++;table()});$('#trade-rows').addEventListener('click',e=>{const b=e.target.closest('[data-event]');if(b)detail(visible.find(x=>x.event_id===Number(b.dataset.event)),b)});$('#case-open').addEventListener('click',()=>{const x=D.rows[profile].find(x=>x.code==='sz.300369'&&x.dry_date===20260825);if(x)detail(x,$('#case-open'))});$('#close-detail').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{cleanup?.();cleanup=null;opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});render();})().catch(window.showResearchDataError);
